        for c in range(W):
            v=int(a[r,c])
            if v==dom: continue
            # find maximal diagonal run containing (r,c) in either direction; must have length>=2
            runs=[]
            for dr,dc in ((1,1),(1,-1)):
                y,x=r-dr,c-dc; nback=0
                while 0<=y<H and 0<=x<W and int(a[y][x])==v:
                    nback+=1; y-=dr; x-=dc
                y,x=r+dr,c+dc; nforw=0
                while 0<=y<H and 0<=x<W and int(a[y][x])==v:
                    nforw+=1; y+=dr; x+=dc
                tot=nback+nforw+1
                if tot>=2:
                    runs.append(((dr,dc),(-nback*dr,-nback*dc),(nforw*dr,nforw*dc),tot))
            for (dir_,s,e,tot) in runs:
                # extend from start s along -dir_ and from end e along dir_ through bg
                for (yy,xx),step in [((s[0]+dir_[0]*-1//1, s[1]+dir_[1]), -dir_), ((e[0],e[1]), dir_)]:
                    yy0,s0=yy,xx
                    while 0<=yy0<H and 0<=xx0<W and int(a[yy0][xx0])==dom:
                        res[yy0][xx0]=v
                        yy0+=step[0]; xx0+=step[1]
            seen=set()
            break
    return res

