                    nback+=1; y-=dr; x-=dc
                y,x=r+dr,c+dc; nforw=0
                while 0<=y<H and 0<=x<W and int(a[y][x])==v:
                    nforw+=1; y+=dr; x+=dc
                tot=nback+nforw+1
                if tot<2: continue
                sy=sy=r-nback*dr; sx=c-nback*dc
                ey=c_end=r+nforw*dr; ex=c+nforw*dc
                # extend from sy backward
                yy,xx=sy-dr,sx-dc
                while 0<=yy<H and 0<=xx<W and int(a[yy][xx])==dom:
                    res[yy][xx]=v; yy-=dr; xx-=dc
                # extend from ey forward
